 const requireValue=(condition,message)=>{if(!condition)throw new Error(message);};
 const clean=log.split(/\r?\n/).map((line)=>{
  if(line.startsWith("\ufeff")){requireValue(/^\ufeff\d{4}-\d\d-\d\dT/.test(line),"Unexpected BOM");line=line.slice(1);}
  line=line.replace(/\x1b\[[0-9;]*m/g,"");
  return line.replace(/^\d{4}-\d\d-\d\dT[0-9:.]+Z /,"");
 });
 const banner=clean.filter(line=>line.startsWith("platform "));
 requireValue(banner.length===1&&banner[0]==="platform linux -- Python 3.12.13, pytest-9.0.3, pluggy-1.6.0","Exact original runtime banner");
 const plugins=clean.filter(line=>line.startsWith("plugins: "));
 requireValue(plugins.length===1&&plugins[0]==="plugins: cov-7.1.0, anyio-4.14.2","Exact observed plugin population");
 requireValue(clean.filter(line=>line==="configfile: pyproject.toml").length===1,"Exact configfile banner");
 const collection=clean.map((line,index)=>({line,index})).filter(row=>/^collected \d+ items$/.test(row.line));
 requireValue(collection.length===1&&Number(collection[0].line.match(/\d+/)[0])===plannedNodes.length,"Original collection equals complete shard plan");
 const summaryMatches=clean.map((line,index)=>({line,index,match:line.match(/^=+\s+(.+?) in ([0-9.]+)s(?: \([0-9:]+\))?\s+=+$/)})).filter(row=>row.match);
 requireValue(summaryMatches.length===1,"Exactly one complete terminal summary");
 const final=summaryMatches[0],counts={};
 for(const chunk of final.match[1].split(", ")){
  const m=chunk.match(/^(\d+) (passed|failed|skipped|xfailed|xpassed|error|errors|warning|warnings)$/);
  requireValue(m!==null,"Unknown terminal category");
  const category=({errors:"error",warnings:"warning"})[m[2]]||m[2];
  requireValue(!(category in counts),"Repeated terminal category");counts[category]=Number(m[1]);
 }
 const failures=clean.filter(line=>line.startsWith("FAILED ")).map(line=>{
  const m=line.match(/^FAILED (tests\/\S+?)(?: - .*)?$/);
  requireValue(m!==null,"Unparsed original failure line");return m[1];
 });
 requireValue(new Set(failures).size===failures.length&&failures.length===(counts.failed||0),"Unique explicit failure population");
 requireValue(!clean.some(line=>/^ERROR /.test(line))&&(counts.error||0)===0,"Original runtime attribution requires no unlocated error");
 const wanted=[];
 for(const node of plannedNodes){
  const path=node.split("::",1)[0];
  requireValue(/^tests\/\S+\.py$/.test(path),"Exact planned test filename");
  if(!wanted.length||wanted[wanted.length-1].path!==path)wanted.push({path,count:0});
  wanted[wanted.length-1].count++;
 }
 requireValue(new Set(wanted.map(g=>g.path)).size===wanted.length,"One contiguous group per planned file");
 const groups=[],observations=[];let total=0,stop=-1;
 for(let index=collection[0].index+1;index<clean.length;index++){
  const line=clean[index];if(/^={5,}/.test(line)){stop=index;break;}
  if(line.trim()==="")continue;
  let match=line.match(/^(tests\/\S+\.py)\s+([.FsxXE]*)(?:\s+\[\s*(\d{1,3})%\])?\s*$/);
  let marks,pct;
  if(match){
   requireValue(groups.length<wanted.length&&match[1]===wanted[groups.length].path,"Actual file order must equal original full plan");
   if(groups.length)requireValue(groups[groups.length-1].markers.length===wanted[groups.length-1].count,"Previous file complete before new header");
   groups.push({path:match[1],markers:"",lines:[]});marks=match[2];pct=match[3];
  }else{
   match=line.match(/^([.FsxXE]*)(?:\s+\[\s*(\d{1,3})%\])?\s*$/);
   requireValue(match!==null&&groups.length>0,"Unrecognized output within progress");
   marks=match[1];pct=match[2];requireValue(marks.length>0||pct!==undefined,"Empty continuation");
  }
  const current=groups[groups.length-1];current.markers+=marks;current.lines.push({line_number:index+1,text:line});
  total+=marks.length;
  requireValue(current.markers.length<=wanted[groups.length-1].count&&total<=plannedNodes.length,"No extra phase markers or invented planned cases");
  if(pct!==undefined)requireValue(Number(pct)===Math.floor(100*total/plannedNodes.length),"Exact printed cumulative progress");
  observations.push({line_number:index+1,marker_count:marks.length,cumulative_markers:total,percentage:pct===undefined?null:Number(pct)});
 }
 requireValue(stop>=0&&stop<=final.index&&groups.length===wanted.length&&total===plannedNodes.length,"Complete original progress population and terminal ordering");
 const markerCounts={},failedFiles={};
 for(const node of failures){requireValue(plannedNodes.includes(node),"Every original failure belongs to exact plan");const path=node.split("::",1)[0];failedFiles[path]=(failedFiles[path]||0)+1;}
 for(let i=0;i<groups.length;i++){
  const group=groups[i];requireValue(group.markers.length===wanted[i].count,"Every original file count equals plan");
  for(const marker of group.markers)markerCounts[marker]=(markerCounts[marker]||0)+1;
  requireValue([...group.markers].filter(x=>x==="F").length===(failedFiles[group.path]||0),"Every failure assigned to its actual file group");
  group.planned_nodes=wanted[i].count;group.all_markers_passed=/^\.+$/.test(group.markers);
 }
 for(const [marker,category] of Object.entries({".":"passed",F:"failed",s:"skipped",x:"xfailed",X:"xpassed",E:"error"}))
  requireValue((markerCounts[marker]||0)===(counts[category]||0),"Full marker and summary reconciliation: "+category);
 return {plan_nodes:plannedNodes.length,groups,observations,marker_counts:markerCounts,summary:final.match[1],summary_counts:counts,failed_nodes:failures,summary_line:final.index+1,progress_end_line:stop+1,collection_line:collection[0].index+1,plugins:plugins[0]};
}

